import{_ as t,a as s,b as o}from"./chunks/yolo_fine-tuning.DTT1tLAE.js";import{_ as n,o as r,c as a,a0 as i}from"./chunks/framework.Ckbw5VQO.js";const f=JSON.parse('{"title":"YOLO","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/models/yolo.md","filePath":"fr/guide/models/yolo.md"}'),l={name:"fr/guide/models/yolo.md"};function u(d,e,c,p,m,g){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="yolo" tabindex="-1">YOLO <a class="header-anchor" href="#yolo" aria-label="Permalink to &quot;YOLO&quot;">​</a></h1><p>Dans geo-ml, plutôt que d&#39;entraîner un modèle de zéro (ce qui demanderait des millions d&#39;images), on part d&#39;un modèle <strong>YOLOv8 déjà entraîné</strong> sur un grand jeu d&#39;images généralistes : il sait déjà reconnaître des formes, des contours, des textures. Puis, on le <strong>spécialise ensuite sur notre tâche</strong> (<em>fine-tuning</em>). C&#39;est à dire qu&#39;on poursuit son entraînement sur nos deux classes, <strong>piscines</strong> &amp; <strong>bâtiments</strong>, avec un petit jeu d&#39;images IGN. Le modèle réutilise ce qu&#39;il sait déjà voir et apprend juste à reconnaître nos objets.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong><a href="https://arxiv.org/abs/2208.00773" target="_blank" rel="noreferrer">YOLO</a></strong> (<em>You Only Look Once</em>) est une famille de modèles de <strong>détection d&#39;objets</strong> : à partir d&#39;une image, ils renvoient une liste de <strong>boîtes englobantes</strong>, chacune avec une <strong>classe</strong> et un <strong>score de confiance</strong>. C&#39;est le modèle au cœur de ce projet.</p></div><h2 id="principe-de-fonctionnement" tabindex="-1"><a href="https://blent.ai/blog/a/detection-images-yolo-tensorflow" target="_blank" rel="noreferrer">Principe de fonctionnement</a> <a class="header-anchor" href="#principe-de-fonctionnement" aria-label="Permalink to &quot;[Principe de fonctionnement](https://blent.ai/blog/a/detection-images-yolo-tensorflow)&quot;">​</a></h2><img src="'+t+'" style="display:block;margin:1.5rem auto;width:100%;height:auto;"><h3 id="🔹-avant-yolo-deux-etapes-deux-reseaux-ex-faster-r-cnn" tabindex="-1">🔹 Avant YOLO : deux étapes, deux réseaux (ex. <a href="https://arxiv.org/abs/1506.01497" target="_blank" rel="noreferrer">Faster R-CNN</a>) <a class="header-anchor" href="#🔹-avant-yolo-deux-etapes-deux-reseaux-ex-faster-r-cnn" aria-label="Permalink to &quot;🔹 Avant YOLO : deux étapes, deux réseaux (ex. [Faster R-CNN](https://arxiv.org/abs/1506.01497))&quot;">​</a></h3><p>Le détecteur/modèle passe l&#39;image dans le réseau <strong>plusieurs fois</strong> :</p><ol><li><strong>Proposer</strong> des centaines de régions susceptibles de contenir un objet.</li><li><strong>Classer</strong> chaque région <em>une par une</em> en la repassant dans un CNN.</li></ol><p>=&gt; Beaucoup de calculs répétés : <strong>précis, mais lent</strong>.</p><h3 id="🔹-yolo-fait-tout-en-une-seule-passe" tabindex="-1">🔹 <a href="https://medium.com/@fatimazahra.belharar/object-detection-using-cnn-an-introduction-to-the-yolo-algorithm-df0f7b173c6" target="_blank" rel="noreferrer">YOLO fait tout en <strong>une seule passe</strong></a> : <a class="header-anchor" href="#🔹-yolo-fait-tout-en-une-seule-passe" aria-label="Permalink to &quot;🔹 [YOLO fait tout en **une seule passe**](https://medium.com/@fatimazahra.belharar/object-detection-using-cnn-an-introduction-to-the-yolo-algorithm-df0f7b173c6) :&quot;">​</a></h3><p>L&#39;image traverse le réseau <strong>une seule fois</strong> et tout est prédit d&#39;un coup :</p><ol><li>L&#39;image est redimensionnée (ici <strong>640×640</strong>) et passée <strong>une seule fois</strong> dans le CNN.</li><li>Le réseau découpe l&#39;image en grille et prédit directement, pour chaque cellule, des boîtes candidates : position <code>(cx, cy)</code>, taille <code>(w, h)</code>, score d&#39;objet et classe - <strong>le tout simultanément</strong>.</li><li>Un simple nettoyage final (<strong>NMS</strong>) supprime les doublons. Ce n&#39;est plus un réseau, juste un filtre.</li></ol><p>=&gt; Une seule traversée du réseau : <strong>rapide</strong> (idéal pour le temps réel &amp; le navigateur), au prix d&#39;une précision un peu moindre sur les objets très petits ou très nombreux.</p><h2 id="nms-non-maximum-suppression" tabindex="-1"><a href="https://learnopencv.com/non-maximum-suppression-theory-and-implementation-in-pytorch/" target="_blank" rel="noreferrer">NMS (Non-Maximum Suppression)</a> <a class="header-anchor" href="#nms-non-maximum-suppression" aria-label="Permalink to &quot;[NMS (Non-Maximum Suppression)](https://learnopencv.com/non-maximum-suppression-theory-and-implementation-in-pytorch/)&quot;">​</a></h2><p>Un même objet déclenche souvent <strong>plusieurs boîtes qui se chevauchent</strong>. Le <strong>Non-Maximum Suppression</strong> (NMS) ne garde que la meilleure :</p><ol><li><strong>Trier</strong> les boîtes par score de confiance, de la plus élevée à la plus faible.</li><li><strong>Garder</strong> la boîte en tête de liste, puis <strong>supprimer</strong> toutes celles qui la recouvrent trop. c&#39;est-à-dire dont l&#39;<strong>IoU</strong> (<em>Intersection over Union</em>, l&#39;aire commune divisée par l&#39;aire totale) dépasse un seuil fixé.</li><li><strong>Répéter</strong> sur les boîtes restantes jusqu&#39;à ce qu&#39;il n&#39;en reste plus à traiter.</li></ol><p>=&gt; Résultat : <strong>une seule boîte par objet</strong>, celle dont le modèle est le plus sûr.</p><img src="'+s+'" style="display:block;margin:1.5rem auto;width:100%;height:auto;"><div class="info custom-block"><p class="custom-block-title">Dans ce projet, le NMS est fait en JavaScript</p><p>On exporte le modèle ONNX <strong>sans NMS embarqué</strong>, car cette opération passe mal dans ONNX Runtime Web. Le navigateur fait donc le NMS (<code>frontend/src/inference/postprocess.js</code>)</p><p>=&gt; C&#39;est plus fiable</p></div><h2 id="yolov8n" tabindex="-1"><a href="https://docs.ultralytics.com/models/yolov8#overview" target="_blank" rel="noreferrer">YOLOv8n</a> <a class="header-anchor" href="#yolov8n" aria-label="Permalink to &quot;[YOLOv8n](https://docs.ultralytics.com/models/yolov8#overview)&quot;">​</a></h2><h3 id="choix-du-modele-nano" tabindex="-1">Choix du modèle nano <a class="header-anchor" href="#choix-du-modele-nano" aria-label="Permalink to &quot;Choix du modèle nano&quot;">​</a></h3><p>La gamme YOLOv8 propose cinq tailles. Le choix dépend du contexte de déploiement. ici, le modèle doit <strong>tourner dans le navigateur via ONNX Runtime Web</strong>, ce qui impose une contrainte forte sur la taille du fichier <code>.onnx</code>.</p><table tabindex="0"><thead><tr><th>Variante</th><th>Paramètres</th><th>Taille ONNX</th><th>Usage</th></tr></thead><tbody><tr><td><strong>YOLOv8n</strong></td><td>~3 M</td><td>~6 MB</td><td>navigateur, mobile ✅</td></tr><tr><td>YOLOv8s</td><td>~11 M</td><td>~22 MB</td><td>bon compromis, chargement acceptable</td></tr><tr><td>YOLOv8m</td><td>~25 M</td><td>~50 MB</td><td>serveur GPU</td></tr><tr><td>YOLOv8l / x</td><td>43–68 M</td><td>&gt;80 MB</td><td>précision max, GPU requis</td></tr></tbody></table><p><code>yolov8n</code> est le défaut du projet. <code>yolov8s</code> reste utilisable en browser si on accepte un chargement plus long.</p><h3 id="fine-tuning-sur-piscines-batiments" tabindex="-1">Fine-tuning sur piscines &amp; bâtiments <a class="header-anchor" href="#fine-tuning-sur-piscines-batiments" aria-label="Permalink to &quot;Fine-tuning sur piscines &amp; bâtiments&quot;">​</a></h3><p>Entraîner un détecteur/modèle de zéro demanderait des millions d&#39;images et des semaines de calcul GPU. Le <strong>fine-tuning</strong> contourne ce coût : au lieu de tout réapprendre, on part d&#39;un modèle YOLOv8 déjà entraîné sur <strong><a href="https://cocodataset.org/" target="_blank" rel="noreferrer">COCO</a></strong> (80 classes d&#39;objets du quotidien, voitures, personnes, animaux…) et on le spécialise sur nos deux classes.</p><img src="'+o+'" style="display:block;margin:1.5rem auto;width:100%;height:auto;"> L&#39;idée clé : un détecteur se décompose en deux parties. <ul><li>Le <strong>backbone</strong> a déjà appris à extraire des caractéristiques visuelles génériques, contours, textures, formes. Ces compétences sont <em>universelles</em>, valables pour n&#39;importe quel objet, donc on les <strong>conserve telles quelles</strong> (on dit qu&#39;on « fige » ces couches).</li><li>La <strong>tête de détection</strong> (<em>detection head</em>) est la partie qui décide <em>quel objet</em> et <em>où</em>. C&#39;est elle qu&#39;on <strong>réentraîne</strong> sur nos images IGN annotées (piscines / bâtiments).</li></ul><div class="tip custom-block"><p class="custom-block-title">Résultat</p><p>le modèle réutilise tout son savoir visuel et n&#39;apprend que ce qui nous est spécifique, en quelques dizaines d&#39;<strong>epochs</strong> (passages sur le jeu de données) au lieu de milliers. Les poids ainsi affinés sont ensuite exportés en <code>.onnx</code> pour tourner dans le navigateur.</p></div>',30)])])}const v=n(l,[["render",u]]);export{f as __pageData,v as default};
